sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    var jsonObj = api.data.approval_action_per_equipment.output;
    var numOfEquip = jsonObj.data.GlideAggregate_Query.length;
    var resArr = [];
    for (var i = 0; i < numOfEquip; i++) {
        var loc = {
            id: jsonObj.data.GlideAggregate_Query[i].groupBy[0].value,
            label: jsonObj.data.GlideAggregate_Query[i].groupBy[0].displayValue
        } ; 
        resArr.push(loc); 
    }
    return JSON.stringify(resArr);
}
